import { Brainteaser } from './cards';

function makeB(id: number, diff: 'easy' | 'medium' | 'hard', q: string, correct: string, wrong: [string, string, string]): Brainteaser {
  const all = [correct, ...wrong];
  const shift = (id * 7 + 3) % 4;
  const options = [all[shift % 4], all[(shift + 1) % 4], all[(shift + 2) % 4], all[(shift + 3) % 4]];
  return { id, difficulty: diff, question: q, options, correctAnswer: options.indexOf(correct) };
}

